def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def pts(poly,s,ox,oy,minx,maxy):return ' '.join(f'{ox+(x-minx)*s:.1f},{oy+(maxy-y)*s:.1f}' for x,y in poly)
